package com.fulldesign.skinstudio;
import android.app.Activity;
import android.os.Bundle;
import android.content.Intent;
import android.net.Uri;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import android.database.Cursor;
import android.provider.OpenableColumns;
import java.io.*;
import java.util.*;

public class MainActivity extends Activity {
 int bg=Color.rgb(12,13,22), panel=Color.rgb(24,26,42), purple=Color.rgb(148,88,255), cyan=Color.rgb(66,216,224), white=Color.rgb(246,246,255), muted=Color.rgb(164,171,196);
 LinearLayout root, body; Bitmap bitmap; Uri imageUri; ImageView preview; TextView filename,fovText; SeekBar fov;
 ArrayList<Uri> pack=new ArrayList<>(); ArrayList<String> names=new ArrayList<>(); int page=0;
 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable bgd(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}
 TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,1);return t;}
 void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
 TextView btn(String s,int color,Runnable r){TextView t=txt(s,14,white,true);t.setGravity(17);pad(t,12,14,12,14);t.setBackground(bgd(color,14));t.setOnClickListener(v->r.run());return t;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);render(0);}
 void render(int p){page=p;root=col();root.setBackgroundColor(bg);setContentView(root);
  LinearLayout header=col();pad(header,20,20,20,8);LinearLayout brand=row();TextView logo=txt("F",24,white,true);logo.setGravity(17);logo.setBackground(bgd(purple,13));brand.addView(logo,lp(44,44));LinearLayout bt=col();pad(bt,12,0,0,0);bt.addView(txt("FULLDESIGN",17,white,true));bt.addView(txt("SKINS STUDIO  •  MOBILE",10,cyan,true));brand.addView(bt,new LinearLayout.LayoutParams(0,-2,1));brand.addView(txt("BETA",11,cyan,true));header.addView(brand);header.addView(space(18));String[] titles={"Seu laboratório de skins","Skin Lab","Pack Mixer","Luvas & FOV"};String[] subs={"Crie, organize e prepare seus arquivos.","Importe e converta imagens.","Organize imagens para seu pack.","Ajuste valores e exporte configurações."};header.addView(txt(titles[p],25,white,true));TextView sub=txt(subs[p],13,muted,false);pad(sub,0,5,0,0);header.addView(sub);root.addView(header);
  ScrollView sc=new ScrollView(this);body=col();pad(body,20,8,20,20);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
  if(p==0)home();if(p==1)skin();if(p==2)packs();if(p==3)settings();
  LinearLayout nav=row();nav.setBackgroundColor(Color.rgb(17,18,30));String[] labels={"⌂ Início","▧ Skin Lab","▤ Packs","⚙ Ajustes"};for(int i=0;i<4;i++){final int n=i;TextView t=txt(labels[i],10,page==i?cyan:muted,page==i);t.setGravity(17);pad(t,2,16,2,16);nav.addView(t,new LinearLayout.LayoutParams(0,-2,1));t.setOnClickListener(v->render(n));}root.addView(nav);
 }
 View space(int h){View v=new View(this);v.setLayoutParams(lp(1,h));return v;}
 void card(View v){LinearLayout c=col();c.setBackground(bgd(panel,20));pad(c,16,16,16,16);c.addView(v);LinearLayout.LayoutParams q=lp(-1,-2);q.bottomMargin=dp(13);body.addView(c,q);}
 LinearLayout heading(String title,String sub){LinearLayout c=col();c.addView(txt(title,17,white,true));TextView d=txt(sub,12,muted,false);pad(d,0,5,0,12);c.addView(d);return c;}
 void home(){LinearLayout h=col();h.setBackground(bgd(Color.rgb(43,30,77),22));pad(h,20,20,20,20);h.addView(txt("YOUR SKIN. YOUR STYLE.",11,cyan,true));TextView big=txt("Transforme suas ideias em skins.",24,white,true);pad(big,0,8,0,8);h.addView(big);h.addView(txt("Importe texturas, organize coleções e prepare arquivos para seu fluxo de trabalho no CS 1.6 Mobile.",13,white,false));TextView go=btn("ABRIR SKIN LAB  →",purple,()->render(1));LinearLayout.LayoutParams g=lp(-1,-2);g.topMargin=dp(15);h.addView(go,g);card(h);feature("01  Skin Lab","Importar imagem e exportar BMP",1);feature("02  Pack Mixer","Organizar uma coleção de imagens",2);feature("03  Luvas & FOV","Gerar arquivo de configuração",3);LinearLayout note=heading("Sobre esta versão","A conversão BMP e a exportação de configuração são funcionais. Visualização 3D e instalação automática exigem modelos e formatos compatíveis com o jogo.");card(note);}
 void feature(String title,String sub,int target){LinearLayout c=row();LinearLayout x=col();x.addView(txt(title,16,white,true));x.addView(txt(sub,12,muted,false));c.addView(x,new LinearLayout.LayoutParams(0,-2,1));c.addView(txt("›",26,purple,true));c.setOnClickListener(v->render(target));card(c);}
 void skin(){LinearLayout c=heading("Imagem selecionada","Escolha uma imagem de textura para visualizar e converter.");preview=new ImageView(this);preview.setBackground(bgd(Color.rgb(8,9,16),14));preview.setScaleType(ImageView.ScaleType.FIT_CENTER);LinearLayout.LayoutParams im=lp(-1,210);im.bottomMargin=dp(12);c.addView(preview,im);if(bitmap!=null)preview.setImageBitmap(bitmap);filename=txt(imageUri==null?"Nenhuma imagem selecionada":name(imageUri),12,muted,false);c.addView(filename);TextView pick=btn("＋  IMPORTAR IMAGEM",purple,()->pick(false));LinearLayout.LayoutParams b=lp(-1,-2);b.topMargin=dp(12);c.addView(pick,b);TextView export=btn("EXPORTAR COMO BMP",Color.rgb(35,111,128),()->{if(bitmap==null){toast("Importe uma imagem primeiro.");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/bmp");i.putExtra(Intent.EXTRA_TITLE,"fulldesign_skin.bmp");startActivityForResult(i,3);});LinearLayout.LayoutParams e=lp(-1,-2);e.topMargin=dp(9);c.addView(export,e);card(c);card(heading("Dica de textura","Prefira imagens nítidas e confirme as dimensões antes de substituir arquivos do jogo. Entrada: imagens compatíveis com Android; saída: BMP de 24 bits."));}
 void packs(){LinearLayout c=heading("Sua coleção", "Selecione várias imagens para organizar uma lista de recursos.");c.addView(btn("＋  ADICIONAR IMAGENS",purple,()->pick(true)));TextView count=txt(pack.size()+" arquivo(s) selecionado(s)",12,cyan,true);pad(count,0,12,0,8);c.addView(count);if(names.isEmpty())c.addView(txt("Ainda não há arquivos. Adicione imagens para começar.",13,muted,false));for(int i=0;i<names.size();i++){final int n=i;LinearLayout r=row();r.addView(txt(String.format(Locale.ROOT,"%02d",i+1),12,cyan,true),lp(34,32));r.addView(txt(names.get(i),13,white,false),new LinearLayout.LayoutParams(0,-2,1));TextView rm=txt("×",22,muted,true);rm.setOnClickListener(v->{pack.remove(n);names.remove(n);render(2);});r.addView(rm);c.addView(r);}if(!names.isEmpty()){TextView clear=btn("LIMPAR COLEÇÃO",Color.rgb(42,44,65),()->{pack.clear();names.clear();render(2);});LinearLayout.LayoutParams x=lp(-1,-2);x.topMargin=dp(12);c.addView(clear,x);}card(c);card(heading("Exportação de pack","Esta versão organiza as imagens. Gerar um pack instalável requer conhecer a estrutura de pastas e os formatos específicos do pack de destino."));}
 void settings(){LinearLayout c=heading("Campo de visão (FOV)","Ajuste o valor e exporte uma configuração de texto.");LinearLayout r=row();r.addView(txt("FOV",14,white,true),new LinearLayout.LayoutParams(0,-2,1));fovText=txt("90",22,cyan,true);r.addView(fovText);c.addView(r);fov=new SeekBar(this);fov.setMax(60);fov.setProgress(30);fov.setProgressTintList(android.content.res.ColorStateList.valueOf(purple));fov.setThumbTintList(android.content.res.ColorStateList.valueOf(cyan));c.addView(fov,lp(-1,42));fov.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int v,boolean u){fovText.setText(""+(60+v));}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});c.addView(txt("60  ───────────────────  120",10,muted,false));TextView save=btn("EXPORTAR CONFIGURAÇÃO .TXT",purple,()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/plain");i.putExtra(Intent.EXTRA_TITLE,"fulldesign_fov.txt");startActivityForResult(i,4);});LinearLayout.LayoutParams x=lp(-1,-2);x.topMargin=dp(14);c.addView(save,x);card(c);LinearLayout gloves=heading("Luvas & recursos","Use o Skin Lab para visualizar imagens de luvas ou adicione-as à coleção no Pack Mixer. A visualização 3D será integrada quando os modelos compatíveis estiverem disponíveis.");gloves.addView(btn("ABRIR PACK MIXER",Color.rgb(42,44,65),()->render(2)));card(gloves);}
 void pick(boolean multi){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);if(multi)i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,multi?2:1);}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(res!=RESULT_OK||data==null)return;try{if(req==1&&data.getData()!=null){imageUri=data.getData();try{getContentResolver().takePersistableUriPermission(imageUri,1);}catch(Exception ignored){}try(InputStream in=getContentResolver().openInputStream(imageUri)){bitmap=BitmapFactory.decodeStream(in);}render(1);}else if(req==2){if(data.getClipData()!=null){for(int j=0;j<data.getClipData().getItemCount();j++)add(data.getClipData().getItemAt(j).getUri());}else if(data.getData()!=null)add(data.getData());render(2);}else if(req==3&&data.getData()!=null){bmp(data.getData(),bitmap);toast("BMP exportado.");}else if(req==4&&data.getData()!=null){int value=fov==null?90:60+fov.getProgress();try(OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(("// Fulldesign Skins Studio\nfov "+value+"\\n").getBytes("UTF-8"));}toast("Configuração exportada.");}}catch(Exception e){toast("Erro: "+e.getMessage());}}
 void add(Uri u){pack.add(u);names.add(name(u));try{getContentResolver().takePersistableUriPermission(u,1);}catch(Exception ignored){}}
 String name(Uri u){try(Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst()){int n=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(n>=0)return c.getString(n);}}catch(Exception ignored){}return "imagem";}
 void bmp(Uri uri,Bitmap b)throws Exception{int w=b.getWidth(),h=b.getHeight(),stride=(w*3+3)&~3,size=stride*h;try(DataOutputStream o=new DataOutputStream(getContentResolver().openOutputStream(uri))){o.write('B');o.write('M');le(o,54+size);les(o,0);les(o,0);le(o,54);le(o,40);le(o,w);le(o,h);les(o,1);les(o,24);le(o,0);le(o,size);le(o,2835);le(o,2835);le(o,0);le(o,0);byte[] pad=new byte[stride-w*3];for(int y=h-1;y>=0;y--){for(int x=0;x<w;x++){int c=b.getPixel(x,y);o.write(Color.blue(c));o.write(Color.green(c));o.write(Color.red(c));}o.write(pad);}}}
 void le(DataOutputStream o,int v)throws IOException{o.write(v&255);o.write(v>>8&255);o.write(v>>16&255);o.write(v>>24&255);}void les(DataOutputStream o,int v)throws IOException{o.write(v&255);o.write(v>>8&255);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
